const EditClientModal: React.FC<{ 
    client: Client; 
    onClose: () => void; 
    onSave: (id: string, data: Partial<Client>) => Promise<void> 
}> = ({ client, onClose, onSave }) => {
    const [name, setName] = useState(client.name);
    const [isSaving, setIsSaving] = useState(false);

