                    {[1,2,3,4,5,6].map(i => (
                        <div key={i} className="bg-white p-5 rounded-xl shadow-sm border border-gray-100 h-48 animate-pulse">
                            <div className="h-4 bg-gray-200 rounded w-2/3 mb-4"></div>
                            <div className="h-3 bg-gray-100 rounded w-1/2 mb-8"></div>
