const ClientDetailModal: React.FC<{ 
    client: Client; 
    onClose: () => void;
    onAddressRemoved: () => void;
}> = ({ client, onClose, onAddressRemoved }) => {
    const [orders, setOrders] = useState<Order[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [filterYear, setFilterYear] = useState(new Date().getFullYear());
    const [filterMonth, setFilterMonth] = useState(new Date().getMonth() + 1);
    const [addrToDelete, setAddrToDelete] = useState<DeliveryInfo['address'] | null>(null);

    useEffect(() => {
        const load = async () => {
            const data = await getOrdersByClientId(client.id);
            setOrders(data);
            setIsLoading(false);
        };
        load();
    }, [client.id]);

    const years = useMemo(() => {
        const currentYear = new Date().getFullYear();
        return Array.from({ length: 5 }, (_, i) => currentYear - i);
    }, []);

    const months = [
        { v: 1, n: 'Janeiro' }, { v: 2, n: 'Fevereiro' }, { v: 3, n: 'Março' },
        { v: 4, n: 'Abril' }, { v: 5, n: 'Maio' }, { v: 6, n: 'Junho' },
        { v: 7, n: 'Julho' }, { v: 8, n: 'Agosto' }, { v: 9, n: 'Setembro' },
        { v: 10, n: 'Outubro' }, { v: 11, n: 'Novembro' }, { v: 12, n: 'Dezembro' }
    ];

    const revenueOrders = useMemo(() => {
        return orders.filter(o => REVENUE_ORDER_STATUSES.includes(o.status));
    }, [orders]);

    const filteredRevenueOrders = useMemo(() => {
        return revenueOrders.filter(o => {
            if (!o.createdAt || !o.createdAt.toDate) return false;
            const date = o.createdAt.toDate();
            return date.getFullYear() === filterYear && (date.getMonth() + 1) === filterMonth;
        });
    }, [revenueOrders, filterYear, filterMonth]);

    const topProducts = useMemo(() => {
        const counts: Record<string, { name: string, qty: number }> = {};
        revenueOrders.forEach(o => {
            o.items.forEach(item => {
                const key = `${item.name}-${item.option || ''}`;
                if (!counts[key]) counts[key] = { name: item.name, qty: 0 };
                counts[key].qty += item.quantity;
            });
        });
        return Object.values(counts).sort((a,b) => b.qty - a.qty).slice(0, 5);
    }, [revenueOrders]);

    const monthTotal = filteredRevenueOrders.reduce((acc, o) => acc + (o.total || 0) + (o.deliveryFee || 0), 0);

    const handleConfirmAddressRemove = async () => {
        if (!addrToDelete) return;
        await removeClientAddress(client.id, addrToDelete);
        setAddrToDelete(null);
        onAddressRemoved();
    };

    return (
        <div className="fixed inset-0 bg-white z-[95] flex flex-col animate-slide-in-up">
            <header className="p-4 border-b flex items-center justify-between bg-white sticky top-0 z-10 h-16 shadow-sm">
                <div className="flex items-center gap-3 min-w-0">
                    <button onClick={onClose} className="p-2 -ml-2 hover:bg-gray-100 rounded-full transition-colors">
                        <ArrowLeftIcon className="w-6 h-6 text-gray-600"/>
                    </button>
                    <div className="truncate">
                        <h2 className="font-bold text-lg text-brand-text truncate">{client.name}</h2>
                        <p className="text-[10px] text-gray-500 font-medium">{formatWhatsapp(client.id)}</p>
                    </div>
                </div>
                <button onClick={onClose} className="p-2 hover:bg-gray-100 rounded-full text-gray-400">
                    <XIcon className="w-6 h-6"/>
                </button>
            </header>

            <div className="flex-1 overflow-y-auto p-4 space-y-8 max-w-4xl mx-auto w-full no-scrollbar">
                <section className="bg-gray-50 p-5 rounded-2xl flex flex-wrap gap-4 items-end border border-gray-100 shadow-inner">
                    <div className="flex-1 min-w-[140px]">
                        <label className="block text-[10px] font-bold text-gray-400 uppercase mb-1.5 tracking-wider">Período</label>
                        <div className="flex gap-2">
                             <select 
                                value={filterMonth} 
                                onChange={e => setFilterMonth(Number(e.target.value))}
                                className="flex-1 p-2 rounded-xl border bg-white text-sm outline-none focus:ring-2 focus:ring-brand-primary font-medium"
                            >
                                {months.map(m => <option key={m.v} value={m.v}>{m.n}</option>)}
                            </select>
                             <select 
                                value={filterYear} 
                                onChange={e => setFilterYear(Number(e.target.value))}
                                className="w-24 p-2 rounded-xl border bg-white text-sm outline-none focus:ring-2 focus:ring-brand-primary font-medium"
                            >
                                {years.map(y => <option key={y} value={y}>{y}</option>)}
                            </select>
                        </div>
                    </div>
                    <div className="w-full sm:w-auto flex flex-col items-end">
                        <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-1">Faturamento Pago</p>
                        <p className="text-3xl font-black text-brand-primary drop-shadow-sm">{formatPrice(monthTotal)}</p>
                    </div>
                </section>

                {isLoading ? (
                    <div className="flex flex-col items-center justify-center py-20 gap-4">
                        <SpinnerIcon className="w-10 h-10 text-brand-primary" />
                        <p className="animate-pulse text-gray-400 font-bold text-sm">Carregando histórico do cliente...</p>
                    </div>
                ) : (
                    <>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <section className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm flex flex-col">
                                <h3 className="font-bold text-gray-800 mb-5 flex items-center gap-2">
                                    <div className="w-8 h-8 rounded-lg bg-brand-secondary/40 flex items-center justify-center">
                                        <ShoppingBagIcon className="w-5 h-5 text-brand-primary"/>
                                    </div>
                                    Favoritos do Cliente
                                </h3>
                                {topProducts.length > 0 ? (
                                    <div className="space-y-4">
                                        {topProducts.map((p, i) => (
                                            <div key={i} className="flex justify-between items-center text-sm p-3 bg-gray-50/50 rounded-xl hover:bg-gray-50 transition-colors">
                                                <span className="text-gray-700 font-semibold">{p.name}</span>
                                                <span className="bg-brand-primary text-white px-3 py-1 rounded-full font-bold text-[10px]">
                                                    {p.qty}x
                                                </span>
                                            </div>
                                        ))}
                                    </div>
                                ) : (
                                    <div className="flex-1 flex items-center justify-center">
                                        <p className="text-sm text-gray-400 italic">Nenhum produto favorito ainda.</p>
                                    </div>
                                )}
                            </section>

                            <section className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm">
                                <h3 className="font-bold text-gray-800 mb-5 flex items-center gap-2">
                                    <div className="w-8 h-8 rounded-lg bg-brand-secondary/40 flex items-center justify-center">
                                        <MapPinIcon className="w-5 h-5 text-brand-primary"/>
                                    </div>
                                    Locais de Entrega
                                </h3>
                                <div className="space-y-3">
                                    {client.addresses?.length > 0 ? client.addresses.map((addr, i) => (
                                        <div key={i} className="flex justify-between items-center bg-gray-50 p-4 rounded-xl group hover:border-brand-primary/20 border border-transparent transition-all">
                                            <div className="text-[11px] text-gray-600 leading-relaxed">
                                                <p className="font-black text-brand-text text-xs uppercase">{addr.street}, {addr.number}</p>
                                                <p>{addr.neighborhood} - {addr.cep}</p>
                                            </div>
                                            <button 
                                                onClick={() => setAddrToDelete(addr)}
                                                className="p-2.5 text-gray-300 hover:text-red-500 hover:bg-red-50 rounded-xl transition-all"
                                            >
                                                <TrashIcon className="w-5 h-5" />
                                            </button>
                                        </div>
                                    )) : <p className="text-sm text-gray-400 italic text-center py-4">Nenhum endereço salvo.</p>}
                                </div>
                            </section>
                        </div>

                        <section className="pb-10">
                            <h3 className="font-bold text-gray-800 mb-4 px-1 flex items-center gap-2">
                                <CalendarIcon className="w-5 h-5 text-gray-400"/>
                                Histórico de Pedidos Pagos
                            </h3>
                            <div className="space-y-4">
                                {filteredRevenueOrders.length > 0 ? filteredRevenueOrders.map(o => (
                                    <div key={o.id} className="bg-white border border-gray-100 p-5 rounded-2xl shadow-sm group hover:shadow-md transition-shadow">
                                        <div className="flex justify-between items-start">
                                            <div>
                                                <div className="flex items-center gap-2">
                                                    <span className="text-[10px] font-black text-brand-primary bg-brand-secondary/50 px-2 py-0.5 rounded-lg tracking-wider">#{o.orderNumber}</span>
                                                    <p className="text-[10px] text-gray-400 font-bold uppercase">{formatTimestamp(o.createdAt)}</p>
