const ClientsView: React.FC = () => {
    const [clients, setClients] = useState<Client[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [search, setSearch] = useState('');
    const [editingClient, setEditingClient] = useState<Client | null>(null);
    const [clientToDelete, setClientToDelete] = useState<Client | null>(null);
    const [viewingClient, setViewingClient] = useState<Client | null>(null);

    const loadClients = async () => {
        setIsLoading(true);
        try {
            const data = await getClients();
            const clientsToSync = data.filter((c: any) => c.needsSync);
            if (clientsToSync.length > 0) {
                await Promise.all(clientsToSync.map(c => syncClientStats(c.id)));
                const updatedData = await getClients();
                setClients(updatedData);
            } else {
                setClients(data);
            }
        } catch (e) {
            console.error("Error loading clients", e);
        } finally {
            setIsLoading(false);
        }
    };

    useEffect(() => {
        loadClients();
    }, []);

    const filteredClients = useMemo(() => {
        const query = search.toLowerCase().trim();
        return clients.filter(c => 
            c.name.toLowerCase().includes(query) || 
            c.id.includes(query.replace(/\D/g, ''))
        );
    }, [clients, search]);

    const handleSaveClient = async (id: string, data: Partial<Client>) => {
        await updateClient(id, data);
        setEditingClient(null);
        loadClients();
    };

    const handleDeleteClient = async () => {
        if (!clientToDelete) return;
        await deleteClient(clientToDelete.id);
        setClientToDelete(null);
        loadClients();
    };

    return (
        <div className="space-y-6 max-w-7xl mx-auto">
            <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 flex flex-col sm:flex-row gap-4 items-center">
                <div className="relative flex-grow w-full">
                    <SearchIcon className="absolute left-4 top-1/2 -translate-y-1/2 h-5 w-5 text-gray-400" />
                    <input
                        type="text"
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        placeholder="Pesquisar por nome ou WhatsApp..."
                        className="w-full bg-gray-50 border-transparent rounded-full py-3 pl-12 pr-6 text-gray-900 focus:outline-none focus:ring-2 focus:ring-brand-primary text-sm font-medium transition-all"
                    />
                </div>
                <div className="flex-shrink-0 px-6 py-3 bg-brand-secondary/30 rounded-xl text-[10px] font-black text-brand-primary uppercase tracking-widest flex items-center gap-2 border border-brand-secondary/50">
                    <UsersIcon className="w-4 h-4" />
                    {clients.length} Clientes
                </div>
            </div>

            {isLoading ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {[1,2,3,4,5,6].map(i => (
                        <div key={i} className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100 h-60 animate-pulse">
                            <div className="h-5 bg-gray-100 rounded-lg w-2/3 mb-4"></div>
                            <div className="h-4 bg-gray-50 rounded-lg w-1/2 mb-10"></div>
                            <div className="grid grid-cols-2 gap-3">
                                <div className="h-16 bg-gray-50 rounded-xl"></div>
                                <div className="h-16 bg-gray-50 rounded-xl"></div>
                            </div>
                        </div>
                    ))}
                </div>
            ) : filteredClients.length > 0 ? (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {filteredClients.map(client => (
                        <ClientCard 
                            key={client.id} 
                            client={client} 
                            onEdit={setEditingClient} 
                            onDelete={setClientToDelete}
                            onView={setViewingClient}
                        />
                    ))}
                </div>
            ) : (
                <div className="text-center py-24 bg-white rounded-3xl border border-dashed border-gray-200">
                    <div className="w-20 h-20 bg-gray-50 rounded-full flex items-center justify-center mx-auto mb-6">
                        <UsersIcon className="w-10 h-10 text-gray-200" />
                    </div>
                    <h3 className="text-gray-500 font-black text-lg">Nenhum cliente por aqui</h3>
                    <p className="text-gray-400 text-sm mt-1">Refine sua busca ou aguarde novas vendas.</p>
                </div>
            )}

            {editingClient && (
                <EditClientModal 
                    client={editingClient} 
                    onClose={() => setEditingClient(null)} 
                    onSave={handleSaveClient} 
                />
            )}

            {viewingClient && (
                <ClientDetailModal 
                    client={viewingClient} 
                    onClose={() => setViewingClient(null)}
                    onAddressRemoved={loadClients}
                />
            )}

            <ConfirmModal 
                isOpen={!!clientToDelete}
                title="Excluir Cliente?"
                message="Deseja apagar este cadastro do CRM? Os pedidos deste cliente no banco de dados não serão afetados."
                confirmText="Excluir Cadastro"
                onConfirm={handleDeleteClient}
                onCancel={() => setClientToDelete(null)}
            />
        </div>
    );
};

export default ClientsView;
